<?php
$pageTitle='Order Management';$activePage='orders';require_once __DIR__.'/_header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyAdminCsrf();$id=(int)($_POST['id']??0);$status=$_POST['order_status']??'Pending';$allowed=['Pending','Processing','Shipped','Delivered','Cancelled'];if(!in_array($status,$allowed,true)){setFlashMessage('error','Invalid order status.');redirect('orders.php');}try{$s=$pdo->prepare("UPDATE orders SET order_status=? WHERE id=?");$s->execute([$status,$id]);setFlashMessage('success','Order status updated successfully.');}catch(Throwable $e){setFlashMessage('error','Could not update order status.');}redirect('orders.php');}
$orders=$pdo->query("SELECT o.*, u.full_name user_name FROM orders o LEFT JOIN users u ON u.id=o.user_id ORDER BY o.id DESC")->fetchAll();
?>
<div class="admin-title-row"><div><h1>Customer Orders</h1><p>View orders and persist status changes in the database.</p></div></div>
<div class="admin-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Contact</th><th>Total</th><th>Date</th><th>Status / Update</th></tr></thead><tbody>
<?php foreach($orders as $o): ?><tr><td><strong>#<?php echo sanitize($o['order_number']); ?></strong></td><td><?php echo sanitize($o['customer_name']); ?><br><small><?php echo sanitize($o['customer_email']); ?></small></td><td><?php echo sanitize($o['customer_phone']); ?><br><?php echo sanitize($o['city']); ?></td><td><?php echo formatPrice($o['total_amount']); ?></td><td><?php echo sanitize($o['created_at']); ?></td><td><form method="post" class="admin-actions"><input type="hidden" name="csrf_token" value="<?php echo adminCsrfToken(); ?>"><input type="hidden" name="id" value="<?php echo $o['id']; ?>"><select name="order_status"><option <?php echo $o['order_status']==='Pending'?'selected':''; ?>>Pending</option><option <?php echo $o['order_status']==='Processing'?'selected':''; ?>>Processing</option><option <?php echo $o['order_status']==='Shipped'?'selected':''; ?>>Shipped</option><option <?php echo $o['order_status']==='Delivered'?'selected':''; ?>>Delivered</option><option <?php echo $o['order_status']==='Cancelled'?'selected':''; ?>>Cancelled</option></select><button class="admin-btn" type="submit">Update</button></form></td></tr><?php endforeach; ?>
<?php if(!$orders): ?><tr><td colspan="6" class="admin-empty">No orders yet.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require_once __DIR__.'/_footer.php'; ?>
